25	// recorder stands in for the *testing.T handed to fakenexus.New, so that a test
26	// can observe the error the server reports for an unrecorded request without
27	// failing itself. Everything else (Cleanup, Helper, Logf) goes to the real T.
28	// The server answers from another goroutine, hence the mutex.
29	type recorder struct {
30		testing.TB
31		mu   sync.Mutex
32		errs []string
33	}
