35	func (r *recorder) record(args ...any) {
36		r.mu.Lock()
37		defer r.mu.Unlock()
38		r.errs = append(r.errs, strings.TrimSpace(fmt.Sprint(args...)))
39	}
40	
41	func (r *recorder) Errorf(format string, args ...any) { r.record(fmt.Sprintf(format, args...)) }
42	func (r *recorder) Error(args ...any)                 { r.record(args...) }
43	func (r *recorder) Fatalf(format string, args ...any) { r.record(fmt.Sprintf(format, args...)) }
44	func (r *recorder) Fatal(args ...any)                 { r.record(args...) }
