14	
15	// Identity is the account a fixture was recorded as; it comes from the file
16	// name suffix only.
17	type Identity string
18	
19	// The identities of the NX-03 bench.
20	const (
21		Admin     Identity = "admin"
22		Pull      Identity = "pull"
23		Anonymous Identity = "anon"
24	)
25	
26	// RecordPending marks a request-only fixture that the recorder has yet to fill.
27	const RecordPending = "pending"
28	
29	const (
30		fileSuffix    = ".http"
31		identitySep   = "--"
32		exchangeSep   = "###"
33		httpVersion   = "HTTP/1.1"
34		stubEmpty     = "<empty body>"
35		stubHTMLStart = "<HTML body omitted:"
36		// stubOmittedStart opens the summary of a body that is neither JSON nor HTML.
37		stubOmittedStart = "<body omitted:"
38	)
39	
40	// Meta is the commented header of a fixture. Free text is kept raw so that
41	// Format loses nothing.
42	type Meta struct {
43		Scenario     string // the "# scenario:" header, free text; Fixture.Scenario is the file name's part
44		NexusVersion string // first token of the nexus header
45		Edition      string // second token of the nexus header
46		NexusNote    string // the text in parentheses after the edition, without them
47		Measured     string // raw value: a date, optionally followed by ", free text"
48		Account      string
49		Redacted     string
50		State        string // "" = nominal
51		Record       string // "" = replay, "replay", "pending" or "skip: <reason>"
52		RecordedBy   string // "" for an imported NX-03 file
53	}
54	
55	// Exchange is one request and its answer. A request-only exchange (a pending
56	// fixture) has Status 0 and no response part.
57	type Exchange struct {
58		Method, Target, Host string // Target = path + raw query as recorded
59		RequestHeader        http.Header
60		Status               int
61		Reason               string      // reason phrase as recorded; http.StatusText when empty
62		Header               http.Header // response, whitelisted
63		Body                 []byte      // verbatim; nil when Stub != ""
64		Stub                 string      // "<empty body>" or the HTML summary, as written
65	}
66	
67	// Fixture is one file: a header and one or more exchanges.
68	type Fixture struct {
69		// Name is the file name without ".http"; Scenario is the part of Name before
70		// the identity suffix. Meta.Scenario is a different thing: the free text of the
71		// "# scenario:" header, which need not match the file name.
72		Campaign, Name, Scenario string
73		Identity                 Identity
74		Meta                     Meta
75		Exchanges                []Exchange
76	}
77	
78	var (
79		versionPattern = regexp.MustCompile(`^\d+(\.\d+)+(-[0-9A-Za-z.]+)?$`)
80	
81		requiredHeaders = []string{"scenario", "nexus", "measured", "account", "redacted"}
82		optionalHeaders = []string{"state", "record", "recorded-by"}
83	
84		requestOrder  = []string{"Authorization", "Accept"}
85		responseOrder = []string{
86			"Server", "Docker-Distribution-Api-Version", "Www-Authenticate", "Location", "Link",
87			"Docker-Content-Digest", "Content-Type", "Content-Length",
88		}
89		// displayNames are the header names whose written form is not the
90		// canonical one Go uses as a map key.
91		displayNames = map[string]string{"Www-Authenticate": "WWW-Authenticate"}
92	)
93	
94	func parseErr(fileName, format string, args ...any) error {
95		return fmt.Errorf("nexusfixture: %s: %s", fileName, fmt.Sprintf(format, args...))
96	}
97	
98	// Parse reads one fixture file. fileName is the base name, with ".http". A file
99	// is LF only: a carriage return anywhere is refused. A body line made of "###"
100	// preceded by any number of backslashes is read with one backslash less (Format
101	// writes it with one more), so that a body never reads as the exchange separator.
102	func Parse(campaign, fileName string, data []byte) (Fixture, error) {
103		f := Fixture{Campaign: campaign}
104		name, ok := strings.CutSuffix(fileName, fileSuffix)
105		if !ok {
106			return f, parseErr(fileName, "the file name must end in %s", fileSuffix)
107		}
108		f.Name = name
109		i := strings.LastIndex(name, identitySep)
110		if i < 0 {
111			return f, parseErr(fileName, "no identity suffix, want --admin, --pull or --anon")
112		}
113		f.Scenario, f.Identity = name[:i], Identity(name[i+len(identitySep):])
114		switch f.Identity {
115		case Admin, Pull, Anonymous:
116		default:
117			return f, parseErr(fileName, "unknown identity suffix %q, want admin, pull or anon", string(f.Identity))
118		}
119	
120		if bytes.IndexByte(data, '\r') >= 0 {
121			return f, parseErr(fileName, "the file has a carriage return (CRLF line endings): fixtures use LF only")
122		}
123	
124		meta, rest, err := parseMeta(string(data))
125		if err != nil {
126			return f, parseErr(fileName, "%v", err)
127		}
128		f.Meta = meta
129	
130		chunks := splitExchanges(rest)
131		for n, chunk := range chunks {
132			ex, err := parseExchange(chunk, meta.Record == RecordPending)
133			if err != nil {
134				if len(chunks) > 1 {
135					return f, parseErr(fileName, "exchange %d: %v", n+1, err)
136				}
137				return f, parseErr(fileName, "%v", err)
138			}
139			f.Exchanges = append(f.Exchanges, ex)
140		}
141		return f, nil
142	}
143	
144	// nextLine cuts the first line of s; ok is false when s is empty.
145	func nextLine(s string) (line, rest string, ok bool) {
146		if s == "" {
147			return "", "", false
148		}
149		line, rest, _ = strings.Cut(s, "\n")
150		return line, rest, true
151	}
152	
153	// parseMeta reads the "# key: value" lines and the blank line after them.
154	func parseMeta(text string) (Meta, string, error) {
155		raw := map[string]string{}
156		for strings.HasPrefix(text, "#") {
157			var line string
158			line, text, _ = nextLine(text)
159			body, ok := strings.CutPrefix(line, "# ")
160			if !ok {
161				return Meta{}, "", fmt.Errorf("malformed header line, want \"# key: value\"")
162			}
163			key, value, _ := strings.Cut(body, ":")
164			if !isKnownHeader(key) {
165				return Meta{}, "", fmt.Errorf("unknown header %q", key)
166			}
167			if _, dup := raw[key]; dup {
168				return Meta{}, "", fmt.Errorf("header %q given twice", key)
169			}
170			raw[key] = strings.TrimSpace(value)
171		}
172		for _, key := range requiredHeaders {
173			if raw[key] == "" {
174				return Meta{}, "", fmt.Errorf("missing %s header", key)
175			}
176		}
177		m := Meta{
178			Scenario: raw["scenario"], Measured: raw["measured"], Account: raw["account"], Redacted: raw["redacted"],
179			State: raw["state"], Record: raw["record"], RecordedBy: raw["recorded-by"],
180		}
181		if err := parseNexus(&m, raw["nexus"]); err != nil {
182			return Meta{}, "", err
183		}
184		if err := checkMeasured(m.Measured); err != nil {
185			return Meta{}, "", err
186		}
187		if err := checkRecord(m.Record); err != nil {
188			return Meta{}, "", err
189		}
190		line, rest, ok := nextLine(text)
191		if !ok || line != "" {
192			return Meta{}, "", fmt.Errorf("a blank line must separate the headers from the request")
193		}
194		return m, rest, nil
195	}
196	
197	func isKnownHeader(key string) bool {
198		for _, k := range requiredHeaders {
199			if k == key {
200				return true
201			}
202		}
203		for _, k := range optionalHeaders {
204			if k == key {
205				return true
206			}
207		}
208		return false
209	}
210	
211	// parseNexus reads "<version> <EDITION> [(free text)]".
212	func parseNexus(m *Meta, v string) error {
213		version, rest, _ := strings.Cut(v, " ")
214		edition, rest, _ := strings.Cut(strings.TrimSpace(rest), " ")
215		rest = strings.TrimSpace(rest)
216		if !versionPattern.MatchString(version) {
217			return fmt.Errorf("nexus header: %q is not a version", version)
218		}
219		if edition == "" {
220			return fmt.Errorf("nexus header: the edition is missing after the version")
221		}
222		m.NexusVersion, m.Edition = version, edition
223		if rest == "" {
224			return nil
225		}
226		inner, ok := strings.CutPrefix(rest, "(")
227		if ok {
228			inner, ok = strings.CutSuffix(inner, ")")
229		}
230		if !ok {
231			return fmt.Errorf("nexus header: the text after the edition must be in parentheses")
232		}
233		m.NexusNote = inner
234		return nil
235	}
236	
237	func checkMeasured(v string) error {
238		if len(v) < len("2006-01-02") {
239			return fmt.Errorf("measured header: %q does not start with a YYYY-MM-DD date", v)
240		}
241		if _, err := time.Parse("2006-01-02", v[:10]); err != nil {
242			return fmt.Errorf("measured header: does not start with a YYYY-MM-DD date")
243		}
244		if after := v[10:]; after != "" && !strings.HasPrefix(after, ",") {
245			return fmt.Errorf("measured header: the date may only be followed by \", free text\"")
246		}
247		return nil
248	}
249	
250	func checkRecord(v string) error {
251		if reason, ok := strings.CutPrefix(v, "skip: "); ok && strings.TrimSpace(reason) != "" {
252			return nil
253		}
254		if v == "" || v == "replay" || v == RecordPending {
255			return nil
256		}
257		return fmt.Errorf("record header: %q is not replay, pending or skip: <reason>", v)
258	}
259	
260	// splitExchanges cuts the text after the header at each "###" line.
261	func splitExchanges(text string) []string {
262		parts := strings.Split(text, "\n"+exchangeSep+"\n")
263		for i := 0; i < len(parts)-1; i++ {
264			parts[i] += "\n" // the line break the separator consumed
265		}
266		return parts
267	}
268	
269	func parseExchange(text string, pending bool) (Exchange, error) {
270		var ex Exchange
271		line, text, _ := nextLine(text)
272		fields := strings.Fields(line)
273		if len(fields) != 3 || fields[2] != httpVersion {
274			return ex, fmt.Errorf("request line must be \"METHOD target %s\"", httpVersion)
275		}
276		ex.Method, ex.Target = fields[0], fields[1]
277	
278		header, text, blank, err := readHeaders(text)
279		if err != nil {
280			return ex, fmt.Errorf("request: %w", err)
281		}
282		ex.Host = header.Get("Host")
283		header.Del("Host")
284		ex.RequestHeader = header
285		if ex.Host == "" {
286			return ex, fmt.Errorf("the request has no Host header")
287		}
288	
289		if !blank || text == "" {
290			if pending {
291				return ex, nil
292			}
293			return ex, fmt.Errorf("the response is missing (only a pending fixture may hold a request alone)")
294		}
295		if pending {
296			return ex, fmt.Errorf("a pending fixture must not carry a response")
297		}
298		return ex, parseResponse(&ex, text)
299	}
300	
301	func parseResponse(ex *Exchange, text string) error {
302		line, text, _ := nextLine(text)
303		rest, ok := strings.CutPrefix(line, httpVersion+" ")
304		if !ok {
305			return fmt.Errorf("status line must be \"%s <code> <reason>\"", httpVersion)
306		}
307		code, reason, _ := strings.Cut(rest, " ")
308		status, err := strconv.Atoi(code)
309		if err != nil || status < 100 || status > 599 {
310			return fmt.Errorf("status code is not a number from 100 to 599")
311		}
312		// Format trims the status line, so a blank or padded phrase cannot round-trip.
313		ex.Status, ex.Reason = status, strings.TrimSpace(reason)
314	
315		header, text, blank, err := readHeaders(text)
316		if err != nil {
317			return fmt.Errorf("response: %w", err)
318		}
319		if !blank {
320			return fmt.Errorf("a blank line must separate the response headers from the body")
321		}
322		ex.Header = header
323	
324		body := strings.TrimSuffix(text, "\n")
325		if body == stubEmpty || isOmittedStub(body) {
326			ex.Stub = body
327		} else {
328			ex.Body = []byte(unescapeBody(body))
329		}
330		return nil
331	}
332	
333	// isOmittedStub reports whether a body is one of the two summaries Redact writes
334	// in place of a body: "<HTML body omitted: ...>" or "<body omitted: ...>".
335	func isOmittedStub(body string) bool {
336		return (strings.HasPrefix(body, stubHTMLStart) || strings.HasPrefix(body, stubOmittedStart)) && strings.HasSuffix(body, ">")
337	}
338	
339	// isSeparatorLike reports whether a body line is "###" preceded by any number
340	// of backslashes: the lines Format escapes and Parse unescapes.
341	func isSeparatorLike(line string) bool {
342		return strings.HasSuffix(line, exchangeSep) && strings.Trim(line[:len(line)-len(exchangeSep)], `\`) == ""
343	}
344	
345	// mapSeparatorLikeLines applies fn to each body line that isSeparatorLike.
346	func mapSeparatorLikeLines(body string, fn func(string) string) string {
347		lines := strings.Split(body, "\n")
348		for i, l := range lines {
349			if isSeparatorLike(l) {
350				lines[i] = fn(l)
351			}
352		}
353		return strings.Join(lines, "\n")
354	}
355	
356	func escapeBody(body []byte) []byte {
357		return []byte(mapSeparatorLikeLines(string(body), func(l string) string { return `\` + l }))
358	}
359	
360	func unescapeBody(body string) string {
361		return mapSeparatorLikeLines(body, func(l string) string { return l[1:] })
362	}
363	
364	// readHeaders reads "Name: value" lines up to a blank line. blank is false when
365	// the text ended first.
366	func readHeaders(text string) (h http.Header, rest string, blank bool, err error) {
367		h = http.Header{}
368		for {
369			var line string
370			var ok bool
371			line, text, ok = nextLine(text)
372			switch {
373			case !ok:
374				return h, "", false, nil
375			case line == "":
376				return h, text, true, nil
377			case strings.HasPrefix(line, "HTTP/"):
378				return nil, "", false, fmt.Errorf("a blank line must separate the request from the response")
379			}
380			name, value, found := strings.Cut(line, ":")
381			if !found || name == "" {
382				return nil, "", false, fmt.Errorf("malformed header line, want \"Name: value\"")
383			}
384			h.Add(textproto.CanonicalMIMEHeaderKey(name), strings.TrimPrefix(value, " "))
385		}
386	}
387	
388	// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
389	// the recorder or the NX-03 import wrote.
390	func Format(f Fixture) []byte {
391		var b bytes.Buffer
392		writeMeta(&b, f.Meta)
393		for i, ex := range f.Exchanges {
394			if i == 0 {
395				b.WriteString("\n")
396			} else {
397				b.WriteString(exchangeSep + "\n")
398			}
399			writeExchange(&b, ex)
400		}
401		return b.Bytes()
402	}
403	
404	func writeMeta(b *bytes.Buffer, m Meta) {
405		nexus := m.NexusVersion + " " + m.Edition
406		if m.NexusNote != "" {
407			nexus += " (" + m.NexusNote + ")"
408		}
409		lines := []struct{ key, value string }{
410			{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
411			{"account", m.Account}, {"redacted", m.Redacted},
412		}
413		for _, l := range lines {
414			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
415		}
416		for _, l := range []struct{ key, value string }{{"state", m.State}, {"record", m.Record}, {"recorded-by", m.RecordedBy}} {
417			if l.value != "" {
418				fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
419			}
420		}
421	}
422	
423	func writeExchange(b *bytes.Buffer, ex Exchange) {
424		fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
425		writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
426		if ex.Status == 0 {
427			return
428		}
429		reason := ex.Reason
430		if reason == "" {
431			reason = http.StatusText(ex.Status)
432		}
433		b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
434		writeHeaders(b, ex.Header, responseOrder)
435		b.WriteString("\n")
436		if ex.Stub != "" {
437			b.WriteString(ex.Stub)
438		} else {
439			b.Write(escapeBody(ex.Body))
440		}
441		b.WriteString("\n")
442	}
443	
444	// writeHeaders writes the headers in a fixed order (the preferred names first,
445	// then the others sorted) so that a regeneration does not reshuffle a file.
446	func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
447		skipped := map[string]bool{}
448		for _, s := range skip {
449			skipped[s] = true
450		}
451		var names []string
452		for _, p := range preferred {
453			if _, ok := h[p]; ok && !skipped[p] {
454				names = append(names, p)
455			}
456		}
457		var others []string
458		for k := range h {
459			if skipped[k] || contains(preferred, k) {
460				continue
461			}
462			others = append(others, k)
463		}
464		sort.Strings(others)
465		for _, name := range append(names, others...) {
466			display := name
467			if d, ok := displayNames[name]; ok {
468				display = d
469			}
470			for _, v := range h[name] {
471				fmt.Fprintf(b, "%s: %s\n", display, v)
472			}
473		}
474	}
475	
476	func contains(list []string, s string) bool {
477		for _, v := range list {
478			if v == s {
479				return true
480			}
481		}
482		return false
483	}
