2	
3	import (
4		"embed"
5		"fmt"
6		"io/fs"
7		"os"
8		"path"
9		"path/filepath"
10		"runtime"
11		"sort"
12		"strings"
13	)
14	
15	//go:embed fixtures
16	var embedded embed.FS
17	
18	const fixturesDir = "fixtures"
19	
20	// evidenceDirs maps a campaign to the dated measurement it was imported from,
21	// relative to the repository root.
22	var evidenceDirs = map[string]string{
23		"catalog": "docs/measurements/nexus-catalog",
24	}
25	
26	// Load reads the fixtures of one embedded campaign, sorted by name. It refuses
27	// a pending fixture: a request without an answer cannot be replayed.
28	func Load(campaign string) ([]Fixture, error) {
29		sub, err := fs.Sub(embedded, fixturesDir)
30		if err != nil {
31			return nil, fmt.Errorf("nexusfixture: %w", err)
32		}
33		return LoadFS(sub, campaign)
34	}
35	
36	// LoadFS is Load over any file system: it reads <campaign>/*.http from fsys.
37	func LoadFS(fsys fs.FS, campaign string) ([]Fixture, error) {
38		entries, err := fs.ReadDir(fsys, campaign)
39		if err != nil {
40			return nil, fmt.Errorf("nexusfixture: campaign %q: %w", campaign, err)
41		}
42		var fixtures []Fixture
43		for _, e := range entries {
44			if e.IsDir() || !strings.HasSuffix(e.Name(), fileSuffix) {
45				continue
46			}
47			data, err := fs.ReadFile(fsys, path.Join(campaign, e.Name()))
48			if err != nil {
49				return nil, fmt.Errorf("nexusfixture: campaign %q: %w", campaign, err)
50			}
51			f, err := Parse(campaign, e.Name(), data)
52			if err != nil {
53				return nil, err
54			}
55			if f.Meta.Record == RecordPending {
56				return nil, fmt.Errorf("nexusfixture: %s is pending (no recorded answer): run the recorder first", f.Name)
57			}
58			fixtures = append(fixtures, f)
59		}
60		sort.Slice(fixtures, func(i, j int) bool { return fixtures[i].Name < fixtures[j].Name })
61		return fixtures, nil
62	}
63	
64	// Campaigns lists the embedded campaigns, sorted.
65	func Campaigns() []string {
66		entries, err := fs.ReadDir(embedded, fixturesDir)
67		if err != nil {
68			return nil
69		}
70		var names []string
71		for _, e := range entries {
72			if e.IsDir() {
73				names = append(names, e.Name())
74			}
75		}
76		sort.Strings(names)
77		return names
78	}
79	
80	// All loads every embedded campaign.
81	func All() ([]Fixture, error) {
82		var all []Fixture
83		for _, c := range Campaigns() {
84			fixtures, err := Load(c)
85			if err != nil {
86				return nil, err
87			}
88			all = append(all, fixtures...)
89		}
90		return all, nil
91	}
92	
93	// EvidenceDir is the directory under docs/measurements/ whose files a
94	// campaign's unrecorded fixtures are byte-identical to.
95	func EvidenceDir(campaign string) (string, bool) {
96		dir, ok := evidenceDirs[campaign]
97		return dir, ok
98	}
99	
100	// SourceDir is the fixtures directory in the source tree, for the recorder
101	// (the embedded copy is read-only). It never answers with a path that is not
102	// there: under -trimpath runtime.Caller gives a module-relative path, so the
103	// answer is then an empty path and an error.
104	func SourceDir() (string, error) {
105		_, file, _, ok := runtime.Caller(0)
106		if !ok || !filepath.IsAbs(file) {
107			return "", fmt.Errorf("nexusfixture: cannot locate the source tree")
108		}
109		dir := filepath.Join(filepath.Dir(file), fixturesDir)
110		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
111			return "", fmt.Errorf("nexusfixture: cannot locate the source tree: %s is not a directory", dir)
112		}
113		return dir, nil
114	}
