25	// recorder stands in for the *testing.T handed to fakenexus.New, so that a test
26	// can observe the error the server reports for an unrecorded request without
27	// failing itself. Everything else (Cleanup, Helper, Logf) goes to the real T.
28	// The server answers from another goroutine, hence the mutex.
29	type recorder struct {
30		testing.TB
31		mu   sync.Mutex
32		errs []string
33	}
34	
35	func (r *recorder) record(args ...any) {
36		r.mu.Lock()
37		defer r.mu.Unlock()
38		r.errs = append(r.errs, strings.TrimSpace(fmt.Sprint(args...)))
39	}
40	
41	func (r *recorder) Errorf(format string, args ...any) { r.record(fmt.Sprintf(format, args...)) }
42	func (r *recorder) Error(args ...any)                 { r.record(args...) }
43	func (r *recorder) Fatalf(format string, args ...any) { r.record(fmt.Sprintf(format, args...)) }
44	func (r *recorder) Fatal(args ...any)                 { r.record(args...) }
45	
46	func (r *recorder) failures() []string {
47		r.mu.Lock()
48		defer r.mu.Unlock()
49		return append([]string(nil), r.errs...)
50	}
