52	// loadAll returns the embedded NX-03 campaign by name.
53	func loadAll(t *testing.T) map[string]nexusfixture.Fixture {
54		t.Helper()
55		fixtures, err := nexusfixture.Load("catalog")
56		if err != nil {
57			t.Fatalf("Load(catalog): %v", err)
58		}
59		if len(fixtures) == 0 {
60			t.Fatal("the catalog campaign is empty")
61		}
62		byName := make(map[string]nexusfixture.Fixture, len(fixtures))
63		for _, f := range fixtures {
64			byName[f.Name] = f
65		}
66		return byName
67	}
