69	func all(t *testing.T) []nexusfixture.Fixture {
70		t.Helper()
71		fixtures, err := nexusfixture.Load("catalog")
72		if err != nil {
73			t.Fatalf("Load(catalog): %v", err)
74		}
75		return fixtures
