78	// pick returns the named fixtures, failing on a name that does not exist.
79	func pick(t *testing.T, names ...string) []nexusfixture.Fixture {
80		t.Helper()
81		byName := loadAll(t)
82		out := make([]nexusfixture.Fixture, 0, len(names))
83		for _, n := range names {
84			f, ok := byName[n]
