93	// get sends GET target to base as the identity (no Authorization for anonymous)
94	// and returns the answer with its body read. Redirects are not followed.
95	func get(t *testing.T, base, target string, id nexusfixture.Identity) (*http.Response, []byte) {
96		t.Helper()
97		req, err := http.NewRequest(http.MethodGet, base+target, nil)
98		if err != nil {
99			t.Fatalf("NewRequest: %v", err)
100		}
101		if id != nexusfixture.Anonymous {
102			req.SetBasicAuth(fakenexus.User(id), fakenexus.Password)
103		}
104		return do(t, req)
105	}
106	
107	func do(t *testing.T, req *http.Request) (*http.Response, []byte) {
108		t.Helper()
109		client := &http.Client{
110			Transport:     &http.Transport{DisableKeepAlives: true},
111			CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
112		}
113		resp, err := client.Do(req)
114		if err != nil {
115			t.Fatalf("%s %s: %v", req.Method, req.URL, err)
116		}
117		defer func() { _ = resp.Body.Close() }()
118		body, err := io.ReadAll(resp.Body)
119		if err != nil {
120			t.Fatalf("reading %s %s: %v", req.Method, req.URL, err)
121		}
122		return resp, body
123	}
