125	// repositories is the first (only) recorded body of a fixture.
126	func recordedBody(t *testing.T, f nexusfixture.Fixture) []byte {
127		t.Helper()
128		if len(f.Exchanges) == 0 {
129			t.Fatalf("%s has no exchange", f.Name)
130		}
131		return f.Exchanges[0].Body
132	}
