358			{"anon n=1000 reuses the no-n anon fixture", hostGroup, "/v2/_catalog?n=1000", nexusfixture.Anonymous, "catalog-group-connector-30482--anon"},
359			{"pull n=1000 reuses the no-n pull fixture", hostGroup, "/v2/_catalog?n=1000", nexusfixture.Pull, "catalog-group-connector-30482--pull"},
