361			{"hosted n=1000 through its path", hostHTTP, "/repository/docker-hosted/v2/_catalog?n=1000", nexusfixture.Admin, "catalog-hosted-repository--admin"},
362			{"proxy n=1000 through its path, anonymous", hostHTTP, "/repository/docker-proxy/v2/_catalog?n=1000", nexusfixture.Anonymous, "catalog-proxy-repository--anon"},
