371			{"a recorded 404 is not tolerated", hostHTTP, "/v2/_catalog?n=1000", nexusfixture.Anonymous, ""},
372		}
373		for _, c := range cases {
374			t.Run(c.name, func(t *testing.T) {
375				rec := &recorder{TB: t}
376				s := fakenexus.New(rec, all(t)...)
377				resp, body := get(t, s.URL(c.host), c.target, c.id)
378				if c.fixture == "" {
379					if resp.StatusCode != http.StatusNotImplemented {
380						t.Errorf("status = %d, want 501 (unmatched)", resp.StatusCode)
381					}
382					if n := len(rec.failures()); n != 1 {
383						t.Errorf("%d test errors, want 1: %q", n, rec.failures())
384					}
385					return
386				}
387				if errs := rec.failures(); len(errs) != 0 {
388					t.Fatalf("unexpected test errors: %q", errs)
389				}
390				if resp.StatusCode != http.StatusOK {
391					t.Fatalf("status = %d, want 200", resp.StatusCode)
392				}
393				want := recordedBody(t, loadAll(t)[c.fixture])
394				if !bytes.Equal(body, want) {
395					t.Errorf("body = %q, want %q", body, want)
396				}
397				if got := s.Hits(c.fixture); got != 1 {
398					t.Errorf("Hits(%s) = %d, want 1", c.fixture, got)
399				}
400				if resp.Header.Get("Link") != "" {
401					t.Errorf("a tolerated answer carries a Link: %q", resp.Header.Get("Link"))
402				}
403			})
404		}
