15	// Identity is the account a fixture was recorded as; it comes from the file
16	// name suffix only.
17	type Identity string
18	
19	// The identities of the NX-03 bench.
20	const (
21		Admin     Identity = "admin"
22		Pull      Identity = "pull"
23		Anonymous Identity = "anon"
24	)
25	
26	// RecordPending marks a request-only fixture that the recorder has yet to fill.
27	const RecordPending = "pending"
28	
29	const (
30		fileSuffix    = ".http"
31		identitySep   = "--"
32		exchangeSep   = "###"
33		httpVersion   = "HTTP/1.1"
34		stubEmpty     = "<empty body>"
35		stubHTMLStart = "<HTML body omitted:"
36		// stubOmittedStart opens the summary of a body that is neither JSON nor HTML.
37		stubOmittedStart = "<body omitted:"
38	)
