40	// Meta is the commented header of a fixture. Free text is kept raw so that
41	// Format loses nothing.
42	type Meta struct {
43		Scenario     string // the "# scenario:" header, free text; Fixture.Scenario is the file name's part
44		NexusVersion string // first token of the nexus header
45		Edition      string // second token of the nexus header
46		NexusNote    string // the text in parentheses after the edition, without them
47		Measured     string // raw value: a date, optionally followed by ", free text"
48		Account      string
49		Redacted     string
50		State        string // "" = nominal
51		Record       string // "" = replay, "replay", "pending" or "skip: <reason>"
52		RecordedBy   string // "" for an imported NX-03 file
53	}
54	
55	// Exchange is one request and its answer. A request-only exchange (a pending
56	// fixture) has Status 0 and no response part.
57	type Exchange struct {
58		Method, Target, Host string // Target = path + raw query as recorded
59		RequestHeader        http.Header
60		Status               int
61		Reason               string      // reason phrase as recorded; http.StatusText when empty
62		Header               http.Header // response, whitelisted
63		Body                 []byte      // verbatim; nil when Stub != ""
64		Stub                 string      // "<empty body>" or the HTML summary, as written
65	}
66	
67	// Fixture is one file: a header and one or more exchanges.
68	type Fixture struct {
69		// Name is the file name without ".http"; Scenario is the part of Name before
70		// the identity suffix. Meta.Scenario is a different thing: the free text of the
71		// "# scenario:" header, which need not match the file name.
72		Campaign, Name, Scenario string
73		Identity                 Identity
74		Meta                     Meta
75		Exchanges                []Exchange
76	}
77	
78	var (
79		versionPattern = regexp.MustCompile(`^\d+(\.\d+)+(-[0-9A-Za-z.]+)?$`)
80	
81		requiredHeaders = []string{"scenario", "nexus", "measured", "account", "redacted"}
82		optionalHeaders = []string{"state", "record", "recorded-by"}
83	
84		requestOrder  = []string{"Authorization", "Accept"}
85		responseOrder = []string{
86			"Server", "Docker-Distribution-Api-Version", "Www-Authenticate", "Location", "Link",
87			"Docker-Content-Digest", "Content-Type", "Content-Length",
88		}
89		// displayNames are the header names whose written form is not the
90		// canonical one Go uses as a map key.
91		displayNames = map[string]string{"Www-Authenticate": "WWW-Authenticate"}
