94	func parseErr(fileName, format string, args ...any) error {
95		return fmt.Errorf("nexusfixture: %s: %s", fileName, fmt.Sprintf(format, args...))
96	}
97	
98	// Parse reads one fixture file. fileName is the base name, with ".http". A file
99	// is LF only: a carriage return anywhere is refused. A body line made of "###"
100	// preceded by any number of backslashes is read with one backslash less (Format
101	// writes it with one more), so that a body never reads as the exchange separator.
102	func Parse(campaign, fileName string, data []byte) (Fixture, error) {
103		f := Fixture{Campaign: campaign}
104		name, ok := strings.CutSuffix(fileName, fileSuffix)
105		if !ok {
106			return f, parseErr(fileName, "the file name must end in %s", fileSuffix)
107		}
108		f.Name = name
109		i := strings.LastIndex(name, identitySep)
110		if i < 0 {
111			return f, parseErr(fileName, "no identity suffix, want --admin, --pull or --anon")
112		}
113		f.Scenario, f.Identity = name[:i], Identity(name[i+len(identitySep):])
114		switch f.Identity {
115		case Admin, Pull, Anonymous:
116		default:
117			return f, parseErr(fileName, "unknown identity suffix %q, want admin, pull or anon", string(f.Identity))
118		}
119	
120		if bytes.IndexByte(data, '\r') >= 0 {
121			return f, parseErr(fileName, "the file has a carriage return (CRLF line endings): fixtures use LF only")
122		}
123	
124		meta, rest, err := parseMeta(string(data))
125		if err != nil {
126			return f, parseErr(fileName, "%v", err)
127		}
128		f.Meta = meta
129	
130		chunks := splitExchanges(rest)
131		for n, chunk := range chunks {
132			ex, err := parseExchange(chunk, meta.Record == RecordPending)
133			if err != nil {
134				if len(chunks) > 1 {
135					return f, parseErr(fileName, "exchange %d: %v", n+1, err)
136				}
137				return f, parseErr(fileName, "%v", err)
138			}
139			f.Exchanges = append(f.Exchanges, ex)
140		}
141		return f, nil
142	}
