144	// nextLine cuts the first line of s; ok is false when s is empty.
145	func nextLine(s string) (line, rest string, ok bool) {
146		if s == "" {
147			return "", "", false
148		}
149		line, rest, _ = strings.Cut(s, "\n")
150		return line, rest, true
151	}
152	
153	// parseMeta reads the "# key: value" lines and the blank line after them.
154	func parseMeta(text string) (Meta, string, error) {
155		raw := map[string]string{}
156		for strings.HasPrefix(text, "#") {
157			var line string
158			line, text, _ = nextLine(text)
159			body, ok := strings.CutPrefix(line, "# ")
160			if !ok {
161				return Meta{}, "", fmt.Errorf("malformed header line, want \"# key: value\"")
162			}
163			key, value, _ := strings.Cut(body, ":")
164			if !isKnownHeader(key) {
165				return Meta{}, "", fmt.Errorf("unknown header %q", key)
166			}
167			if _, dup := raw[key]; dup {
168				return Meta{}, "", fmt.Errorf("header %q given twice", key)
169			}
170			raw[key] = strings.TrimSpace(value)
171		}
172		for _, key := range requiredHeaders {
173			if raw[key] == "" {
174				return Meta{}, "", fmt.Errorf("missing %s header", key)
175			}
176		}
177		m := Meta{
178			Scenario: raw["scenario"], Measured: raw["measured"], Account: raw["account"], Redacted: raw["redacted"],
179			State: raw["state"], Record: raw["record"], RecordedBy: raw["recorded-by"],
180		}
