211	// parseNexus reads "<version> <EDITION> [(free text)]".
212	func parseNexus(m *Meta, v string) error {
213		version, rest, _ := strings.Cut(v, " ")
214		edition, rest, _ := strings.Cut(strings.TrimSpace(rest), " ")
215		rest = strings.TrimSpace(rest)
216		if !versionPattern.MatchString(version) {
217			return fmt.Errorf("nexus header: %q is not a version", version)
218		}
219		if edition == "" {
220			return fmt.Errorf("nexus header: the edition is missing after the version")
221		}
222		m.NexusVersion, m.Edition = version, edition
223		if rest == "" {
224			return nil
225		}
226		inner, ok := strings.CutPrefix(rest, "(")
227		if ok {
228			inner, ok = strings.CutSuffix(inner, ")")
229		}
230		if !ok {
231			return fmt.Errorf("nexus header: the text after the edition must be in parentheses")
232		}
233		m.NexusNote = inner
234		return nil
235	}
236	
237	func checkMeasured(v string) error {
238		if len(v) < len("2006-01-02") {
239			return fmt.Errorf("measured header: %q does not start with a YYYY-MM-DD date", v)
240		}
241		if _, err := time.Parse("2006-01-02", v[:10]); err != nil {
242			return fmt.Errorf("measured header: does not start with a YYYY-MM-DD date")
243		}
244		if after := v[10:]; after != "" && !strings.HasPrefix(after, ",") {
245			return fmt.Errorf("measured header: the date may only be followed by \", free text\"")
246		}
247		return nil
248	}
249	
250	func checkRecord(v string) error {
251		if reason, ok := strings.CutPrefix(v, "skip: "); ok && strings.TrimSpace(reason) != "" {
252			return nil
253		}
254		if v == "" || v == "replay" || v == RecordPending {
255			return nil
256		}
257		return fmt.Errorf("record header: %q is not replay, pending or skip: <reason>", v)
258	}
