260	// splitExchanges cuts the text after the header at each "###" line.
261	func splitExchanges(text string) []string {
262		parts := strings.Split(text, "\n"+exchangeSep+"\n")
263		for i := 0; i < len(parts)-1; i++ {
264			parts[i] += "\n" // the line break the separator consumed
265		}
266		return parts
267	}
