269	func parseExchange(text string, pending bool) (Exchange, error) {
270		var ex Exchange
271		line, text, _ := nextLine(text)
272		fields := strings.Fields(line)
273		if len(fields) != 3 || fields[2] != httpVersion {
274			return ex, fmt.Errorf("request line must be \"METHOD target %s\"", httpVersion)
275		}
276		ex.Method, ex.Target = fields[0], fields[1]
277	
278		header, text, blank, err := readHeaders(text)
279		if err != nil {
280			return ex, fmt.Errorf("request: %w", err)
281		}
282		ex.Host = header.Get("Host")
283		header.Del("Host")
284		ex.RequestHeader = header
285		if ex.Host == "" {
286			return ex, fmt.Errorf("the request has no Host header")
287		}
288	
289		if !blank || text == "" {
290			if pending {
291				return ex, nil
292			}
293			return ex, fmt.Errorf("the response is missing (only a pending fixture may hold a request alone)")
294		}
295		if pending {
296			return ex, fmt.Errorf("a pending fixture must not carry a response")
297		}
298		return ex, parseResponse(&ex, text)
299	}
300	
301	func parseResponse(ex *Exchange, text string) error {
302		line, text, _ := nextLine(text)
303		rest, ok := strings.CutPrefix(line, httpVersion+" ")
304		if !ok {
305			return fmt.Errorf("status line must be \"%s <code> <reason>\"", httpVersion)
306		}
307		code, reason, _ := strings.Cut(rest, " ")
308		status, err := strconv.Atoi(code)
309		if err != nil || status < 100 || status > 599 {
310			return fmt.Errorf("status code is not a number from 100 to 599")
311		}
312		// Format trims the status line, so a blank or padded phrase cannot round-trip.
313		ex.Status, ex.Reason = status, strings.TrimSpace(reason)
314	
315		header, text, blank, err := readHeaders(text)
316		if err != nil {
317			return fmt.Errorf("response: %w", err)
318		}
319		if !blank {
320			return fmt.Errorf("a blank line must separate the response headers from the body")
321		}
322		ex.Header = header
323	
324		body := strings.TrimSuffix(text, "\n")
325		if body == stubEmpty || isOmittedStub(body) {
326			ex.Stub = body
327		} else {
328			ex.Body = []byte(unescapeBody(body))
329		}
330		return nil
331	}
332	
333	// isOmittedStub reports whether a body is one of the two summaries Redact writes
334	// in place of a body: "<HTML body omitted: ...>" or "<body omitted: ...>".
335	func isOmittedStub(body string) bool {
336		return (strings.HasPrefix(body, stubHTMLStart) || strings.HasPrefix(body, stubOmittedStart)) && strings.HasSuffix(body, ">")
337	}
338	
339	// isSeparatorLike reports whether a body line is "###" preceded by any number
340	// of backslashes: the lines Format escapes and Parse unescapes.
341	func isSeparatorLike(line string) bool {
342		return strings.HasSuffix(line, exchangeSep) && strings.Trim(line[:len(line)-len(exchangeSep)], `\`) == ""
343	}
344	
345	// mapSeparatorLikeLines applies fn to each body line that isSeparatorLike.
346	func mapSeparatorLikeLines(body string, fn func(string) string) string {
347		lines := strings.Split(body, "\n")
348		for i, l := range lines {
349			if isSeparatorLike(l) {
350				lines[i] = fn(l)
351			}
352		}
353		return strings.Join(lines, "\n")
354	}
355	
356	func escapeBody(body []byte) []byte {
357		return []byte(mapSeparatorLikeLines(string(body), func(l string) string { return `\` + l }))
358	}
359	
360	func unescapeBody(body string) string {
361		return mapSeparatorLikeLines(body, func(l string) string { return l[1:] })
362	}
363	
364	// readHeaders reads "Name: value" lines up to a blank line. blank is false when
365	// the text ended first.
366	func readHeaders(text string) (h http.Header, rest string, blank bool, err error) {
367		h = http.Header{}
368		for {
369			var line string
370			var ok bool
371			line, text, ok = nextLine(text)
372			switch {
373			case !ok:
374				return h, "", false, nil
375			case line == "":
376				return h, text, true, nil
377			case strings.HasPrefix(line, "HTTP/"):
378				return nil, "", false, fmt.Errorf("a blank line must separate the request from the response")
379			}
380			name, value, found := strings.Cut(line, ":")
381			if !found || name == "" {
382				return nil, "", false, fmt.Errorf("malformed header line, want \"Name: value\"")
383			}
384			h.Add(textproto.CanonicalMIMEHeaderKey(name), strings.TrimPrefix(value, " "))
385		}
386	}
387	
388	// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
389	// the recorder or the NX-03 import wrote.
390	func Format(f Fixture) []byte {
391		var b bytes.Buffer
392		writeMeta(&b, f.Meta)
393		for i, ex := range f.Exchanges {
394			if i == 0 {
395				b.WriteString("\n")
396			} else {
397				b.WriteString(exchangeSep + "\n")
398			}
399			writeExchange(&b, ex)
400		}
401		return b.Bytes()
402	}
403	
404	func writeMeta(b *bytes.Buffer, m Meta) {
405		nexus := m.NexusVersion + " " + m.Edition
406		if m.NexusNote != "" {
407			nexus += " (" + m.NexusNote + ")"
408		}
409		lines := []struct{ key, value string }{
410			{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
411			{"account", m.Account}, {"redacted", m.Redacted},
412		}
413		for _, l := range lines {
414			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
415		}
416		for _, l := range []struct{ key, value string }{{"state", m.State}, {"record", m.Record}, {"recorded-by", m.RecordedBy}} {
417			if l.value != "" {
418				fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
419			}
420		}
421	}
422	
423	func writeExchange(b *bytes.Buffer, ex Exchange) {
424		fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
425		writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
426		if ex.Status == 0 {
427			return
428		}
429		reason := ex.Reason
430		if reason == "" {
431			reason = http.StatusText(ex.Status)
432		}
433		b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
434		writeHeaders(b, ex.Header, responseOrder)
435		b.WriteString("\n")
436		if ex.Stub != "" {
437			b.WriteString(ex.Stub)
438		} else {
439			b.Write(escapeBody(ex.Body))
440		}
441		b.WriteString("\n")
442	}
443	
444	// writeHeaders writes the headers in a fixed order (the preferred names first,
445	// then the others sorted) so that a regeneration does not reshuffle a file.
446	func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
447		skipped := map[string]bool{}
448		for _, s := range skip {
449			skipped[s] = true
450		}
451		var names []string
452		for _, p := range preferred {
453			if _, ok := h[p]; ok && !skipped[p] {
454				names = append(names, p)
455			}
456		}
457		var others []string
458		for k := range h {
459			if skipped[k] || contains(preferred, k) {
460				continue
461			}
462			others = append(others, k)
463		}
464		sort.Strings(others)
465		for _, name := range append(names, others...) {
466			display := name
467			if d, ok := displayNames[name]; ok {
468				display = d
469			}
470			for _, v := range h[name] {
471				fmt.Fprintf(b, "%s: %s\n", display, v)
472			}
473		}
474	}
475	
476	func contains(list []string, s string) bool {
477		for _, v := range list {
478			if v == s {
479				return true
480			}
481		}
482		return false
483	}
